        },
        "legacy_source_and_observation_objects_preserved": {
          "type": "boolean"
        },
        "existing_user_confirmed_assignment_and_embedded_relationship_flags_preserved": {
          "type": "boolean"
        },
        "same_TEST_report_is_one_central_evidence_record": {
          "type": "boolean"
        },
        "reportedAt_reuses_actual_source_message_sentAt": {
          "type": "boolean"
        },
        "observedAt_remains_null": {
          "type": "boolean"
        },
        "recordedAt_reuses_original_legacy_record_timestamps": {
