  "additionalProperties": false,
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Student homework evidence and decision plan",
  "$defs": {
    "EvidenceRecord": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sourceKind",
        "actor",
        "sourceRef",
        "reportedAt",
        "observedAt",
        "capturedAt",
        "recordedAt",
        "timeRaw",
        "verificationStatus",
        "verificationDetail",
        "statementProvenance",
        "scope",
        "claim",
        "revision",
        "supersedesEvidenceIds",
        "retractsEvidenceIds",
        "conflictingEvidenceIds",
        "evidenceId"
      ],
      "properties": {
        "evidenceId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "sourceKind": {
          "enum": [
            "user_report",
            "lms_direct_observation",
            "imported_snapshot",
            "inference"
          ]
        },
        "actor": {
          "type": "object",
          "required": [
            "kind",
            "role",
            "id"
          ],
          "additionalProperties": false,
          "properties": {
            "kind": {
              "enum": [
                "user",
                "assistant",
                "native_tool",
                "system"
              ]
            },
            "role": {
              "enum": [
                "teacher",
                "source_collector",
                "reviewer",
                "maintainer",
                "unknown"
              ]
            },
            "id": {
              "type": [
                "string",
                "null"
              ]
            }
          }
        },
        "sourceRef": {
          "type": "object",
          "required": [
            "sourceMessageId",
            "reference",
            "sha256",
            "jsonPointer"
          ],
          "additionalProperties": false,
          "properties": {
            "sourceMessageId": {
              "type": [
                "string",
                "null"
              ]
            },
            "reference": {
              "type": [
                "string",
                "null"
              ]
            },
            "sha256": {
              "type": [
                "string",
                "null"
              ],
              "pattern": "^[a-f0-9]{64}$"
            },
            "jsonPointer": {
              "type": [
                "string",
                "null"
              ]
            }
          }
        },
        "reportedAt": {
          "type": [
            "string",
            "null"
          ],
          "format": "date-time"
        },
        "observedAt": {
          "type": [
            "string",
            "null"
          ],
          "format": "date-time"
        },
        "capturedAt": {
          "type": [
            "string",
            "null"
          ],
          "format": "date-time"
        },
        "recordedAt": {
          "type": "string",
          "format": "date-time"
        },
        "timeRaw": {
          "type": [
            "string",
            "null"
          ]
        },
        "verificationStatus": {
          "enum": [
            "unverified",
            "corroborated",
            "contradicted"
          ]
        },
        "verificationDetail": {
          "type": [
            "string",
            "null"
          ]
        },
        "statementProvenance": {
          "type": "object",
          "required": [
            "confirmed",
            "sourceMessageId"
          ],
          "additionalProperties": false,
          "properties": {
            "confirmed": {
              "type": "boolean"
            },
            "sourceMessageId": {
              "type": [
                "string",
                "null"
              ]
            }
          }
        },
        "scope": {
          "type": "object",
          "required": [
            "studentId",
            "entityIds",
            "fields",
            "window"
          ],
          "additionalProperties": false,
          "properties": {
            "studentId": {
              "type": "string",
              "minLength": 1,
              "maxLength": 256
            },
            "entityIds": {
              "type": "array",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 256
              }
            },
            "fields": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "window": {
              "anyOf": [
                {
                  "type": "null"
                },
                {
                  "type": "object",
                  "required": [
                    "from",
                    "to",
                    "labelRaw"
                  ],
                  "additionalProperties": false,
                  "properties": {
                    "from": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "format": "date-time"
                    },
                    "to": {
                      "type": [
                        "string",
                        "null"
                      ],
                      "format": "date-time"
                    },
                    "labelRaw": {
                      "type": [
                        "string",
                        "null"
                      ]
                    }
                  }
                }
              ]
            }
          }
        },
        "claim": {
          "type": "object",
          "required": [
            "type",
            "value"
          ],
          "additionalProperties": false,
          "properties": {
            "type": {
              "type": "string"
            },
            "value": {}
          }
        },
        "revision": {
          "type": "integer",
          "minimum": 1
        },
        "supersedesEvidenceIds": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 256
          }
        },
        "retractsEvidenceIds": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 256
          }
        },
        "conflictingEvidenceIds": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 256
          }
        }
      }
    },
    "DecisionRecord": {
      "type": "object",
      "required": [
        "decisionId",
        "studentId",
        "targetEntityIds",
        "evidenceIds",
        "ruleVersion",
        "decisionStatus",
        "decisionAuthority",
        "recordedAt"
      ],
      "additionalProperties": false,
      "properties": {
        "decisionId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "studentId": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "targetEntityIds": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 256
          }
        },
        "evidenceIds": {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 256
          }
        },
        "ruleVersion": {
          "type": "string",
          "minLength": 1
        },
        "decisionStatus": {
          "enum": [
            "pending",
            "confirmed",
            "rejected",
            "needs_review"
          ]
        },
        "decisionAuthority": {
          "type": "object",
          "required": [
            "actorKind",
            "role"
          ],
          "additionalProperties": false,
          "properties": {
            "actorKind": {
              "enum": [
                "user",
                "assistant",
                "native_tool",
                "system"
              ]
            },
            "role": {
              "enum": [
                "teacher",
                "source_collector",
                "reviewer",
                "maintainer",
                "unknown"
              ]
            }
          }
        },
        "recordedAt": {
          "type": "string",
          "format": "date-time"
        }
      }
    }
  }
}
